1	// Store scroll positions before HTMX swaps
2	let handScrollPosition = 0;
3	let revealedCardsScrollPosition = 0;
4	
5	/**
6	 * Retain scroll position of hand
7	 */
8	document.addEventListener("htmx:beforeSwap", function (evt) {
9	  // Store the current scroll position of the hand section
10	  const handSection = document.querySelector("#hand-section .hand-cards");
11	  if (handSection) {
12	    handScrollPosition = handSection.scrollLeft;
13	  }
14	
15	  // Store the current scroll position of the revealed cards section
16	  const revealedCardsSection = document.querySelector("#revealed-cards-area");
17	  if (revealedCardsSection) {
18	    revealedCardsScrollPosition = revealedCardsSection.scrollLeft;
19	  }
20	});
21	
22	document.addEventListener("htmx:afterSwap", function (evt) {
23	  // Restore the scroll position of the hand section
24	  const handSection = document.querySelector("#hand-section .hand-cards");
25	  if (handSection && handScrollPosition > 0) {
26	    // Only restore if the scroll position is still valid (not beyond the new scroll width)
27	    const maxScrollLeft = handSection.scrollWidth - handSection.clientWidth;
28	    handSection.scrollLeft = Math.min(handScrollPosition, Math.max(0, maxScrollLeft));
29	  }
30	
31	  // Restore the scroll position of the revealed cards section
32	  const revealedCardsSection = document.querySelector("#revealed-cards-area");
33	  if (revealedCardsSection && revealedCardsScrollPosition > 0) {
34	    // Only restore if the scroll position is still valid (not beyond the new scroll width)
35	    const maxScrollLeft = revealedCardsSection.scrollWidth - revealedCardsSection.clientWidth;
36	    revealedCardsSection.scrollLeft = Math.min(revealedCardsScrollPosition, Math.max(0, maxScrollLeft));
37	  }
38	
39	  // The new menu markup renders with aria-expanded="false"; re-sync it to the
40	  // persistent body state (see setMenuOpen below).
41	  syncMenuToggleAria();
42	});
43	
44	/**
45	 * Hamburger menu toggle.
46	 *
47	 * The open/closed state is a class on <body>, which HTMX never swaps. The menu
48	 * markup itself lives inside #game-container and is replaced on every
49	 * game-state-updated swap, so keeping the state on an element that survives
50	 * swaps avoids racing the swap/settle lifecycle. The toggle uses event
51	 * delegation on the document so it keeps working after the markup is replaced.
52	 */
53	function setMenuOpen(open) {
54	  document.body.classList.toggle("game-menu-open", open);
55	  syncMenuToggleAria();
56	}
57	
58	function syncMenuToggleAria() {
59	  const toggle = document.querySelector("#menu-toggle");
60	  if (toggle) {
61	    toggle.setAttribute("aria-expanded", document.body.classList.contains("game-menu-open") ? "true" : "false");
62	  }
63	}
64	
65	document.addEventListener("click", function (evt) {
66	  if (evt.target.closest("#menu-toggle")) {
67	    setMenuOpen(!document.body.classList.contains("game-menu-open"));
68	    return;
69	  }
70	
71	  // Clicking anywhere outside the open menu closes it. Clicks land on an open
72	  // modal overlay too (it sits above the panel, outside #game-menu), so opening
73	  // a modal then interacting with it dismisses the menu underneath.
74	  if (document.body.classList.contains("game-menu-open") && !evt.target.closest("#game-menu")) {
75	    setMenuOpen(false);
76	  }
77	});
78	
79	/**
80	 * Copy card image to clipboard
81	 */
82	// Function to copy card image to clipboard using proxy URL
83	async function copyCardToClipboard(cardId, face) {
84	  // make sure tracing exists
85	  Hny = Hny || {
86	    inSpanAsync: (a, b, fn, c) => {
87	      console.log("warning: no tracing");
88	      return fn();
89	    },
90	  };
91	  return Hny.inSpanAsync("mtg-deck-shuffler-web", "copy card to clipboard", async (span) => {
92	    const proxyUrl = `/proxy-image?cardId=${encodeURIComponent(cardId)}&face=${encodeURIComponent(face)}`;
93	    const response = await fetch(proxyUrl);
94	    span?.setAttribute("app.response.ok", response.ok);
95	    if (response.ok) {
96	      const blob = await response.blob();
97	      span?.setAttribute("app.blob.type", blob.type);
98	      span?.setAttribute("app.blob.size", blob.size);
99	      await navigator.clipboard.write([
100	        new ClipboardItem({
101	          [blob.type]: blob,
102	        }),
103	      ]);
104	      return true;
105	    }
106	    return false;
107	  });
108	}
109	
110	// Handle clipboard copying when HTMX is about to make the request
111	document.addEventListener("htmx:beforeRequest", async function (evt) {
112	  if (evt.detail.elt.classList.contains("play-button")) {
113	    const button = evt.detail.elt;
114	    const cardId = button.dataset.cardId;
115	    const currentFace = button.dataset.currentFace || "front";
116	
117	    // Try to copy to clipboard first
118	    try {
119	      const success = await copyCardToClipboard(cardId, currentFace);
120	      if (success) {
121	        button.textContent = "Copied!";
122	      } else {
123	        button.textContent = "Copy failed 😨";
124	      }
125	    } catch (clipboardErr) {
126	      console.warn("Failed to copy image to clipboard:", clipboardErr);
127	      button.textContent = "Copy failed 😨";
128	    }
129	
130	    button.disabled = true;
131	  }
132	});
133	
134	// Function to copy card image to clipboard from modal
135	window.copyCardImageToClipboard = async function (event, imageUrl, cardName) {
136	  try {
137	    // Extract card ID and face from the image URL
138	    // URL format: https://cards.scryfall.io/large/front/{first}/{second}/{cardId}.jpg
139	    const urlParts = imageUrl.split("/");
140	    const filename = urlParts[urlParts.length - 1];
141	    const cardId = filename.split(".")[0];
142	    const face = urlParts.includes("/back/") ? "back" : "front";
143	
144	    const success = await copyCardToClipboard(cardId, face);
145	
146	    // Show feedback to user
147	    const copyButton = event.target;
148	    const originalText = copyButton.textContent;
149	
150	    if (success) {
151	      copyButton.textContent = "Copied!";
152	    } else {
153	      copyButton.textContent = "Copy failed 😨";
154	    }
155	    copyButton.disabled = true;
156	
157	    setTimeout(() => {
158	      copyButton.textContent = originalText;
159	      copyButton.disabled = false;
160	    }, 2000);
161	  } catch (error) {
162	    console.warn("Failed to copy image to clipboard:", error);
163	
164	    // Show error feedback
165	    const copyButton = event.target;
166	    const originalText = copyButton.textContent;
167	    copyButton.textContent = "Copy failed 😨";
168	    copyButton.disabled = true;
169	
170	    setTimeout(() => {
171	      copyButton.textContent = originalText;
172	      copyButton.disabled = false;
173	    }, 2000);
174	  }
175	};
176	
177	/**
178	 * Drag/drop for hand card rearranging
179	 */
180	// Drag-and-drop state
181	let draggedCard = null;
182	let draggedFromPosition = null;
183	
184	// Set up drag-and-drop handlers after HTMX swaps
185	document.addEventListener("htmx:afterSwap", function (evt) {
186	  setupHandCardDragAndDrop();
187	});
188	
189	// Also set up on initial page load
190	document.addEventListener("DOMContentLoaded", function () {
191	  setupHandCardDragAndDrop();
192	});
193	
194	function setupHandCardDragAndDrop() {
195	  const handCards = document.querySelectorAll("#hand-cards .card-container[draggable='true']");
196	  const dropZones = document.querySelectorAll("#hand-cards .hand-drop-zone");
197	
198	  handCards.forEach((card) => {
199	    card.addEventListener("dragstart", handleDragStart);
200	    card.addEventListener("dragend", handleDragEnd);
201	  });
202	
203	  dropZones.forEach((zone) => {
204	    zone.addEventListener("dragover", handleDragOver);
205	    zone.addEventListener("dragleave", handleDragLeave);
206	    zone.addEventListener("drop", handleDrop);
207	  });
208	}
209	
210	function handleDragStart(e) {
211	  draggedCard = e.currentTarget;
212	  draggedFromPosition = parseInt(draggedCard.dataset.handPosition);
213	  draggedCard.classList.add("dragging");
214	
215	  draggedCard.classList.remove("card-moved-left"); // if it has these it flickers when dropped
216	  draggedCard.classList.remove("card-moved-right");
217	  draggedCard.classList.remove("dropped-from-left");
218	  draggedCard.classList.remove("dropped-from-right");
219	
220	  e.dataTransfer.effectAllowed = "move";
221	  e.dataTransfer.setData("text/html", draggedCard.innerHTML);
222	}
223	
224	function handleDragEnd(e) {
225	  draggedCard.classList.remove("dragging");
226	  draggedCard = null;
227	  draggedFromPosition = null;
228	}
229	
230	function handleDragOver(e) {
231	  if (e.preventDefault) {
232	    e.preventDefault();
233	  }
234	  e.dataTransfer.dropEffect = "move";
235	  e.currentTarget.classList.add("drag-over");
236	  return false;
237	}
238	
239	function handleDragLeave(e) {
240	  e.currentTarget.classList.remove("drag-over");
241	}
242	
243	function handleDrop(e) {
244	  if (e.stopPropagation) {
245	    e.stopPropagation();
246	  }
247	  e.preventDefault();
248	
249	  const dropZone = e.currentTarget;
250	  dropZone.classList.remove("drag-over");
251	
252	  const dropPosition = parseInt(dropZone.dataset.handPosition);
253	
254	  if (draggedCard && draggedFromPosition !== null) {
255	    // Calculate the target position
256	    // If dropping after the dragged card's current position, adjust by -1 (why?)
257	    let targetPosition = dropPosition;
258	    if (dropPosition > draggedFromPosition) {
259	      targetPosition = dropPosition - 1;
260	    }
261	
262	    if (draggedFromPosition === targetPosition) {
263	      return false;
264	    }
265	
266	    // Get the game ID and expected version from the page
267	    const gameContainer = document.querySelector("#game-container");
268	    const gameId = gameContainer?.dataset.gameId;
269	    const expectedVersion = gameContainer?.dataset.expectedVersion;
270	
271	    if (gameId) {
272	      // Use HTMX to make the POST request
273	      htmx.ajax("POST", `/move-hand-card/${gameId}/${draggedFromPosition}/${targetPosition}`, {
274	        target: "#game-container",
275	        swap: "outerHTML",
276	        values: { "expected-version": expectedVersion },
277	      });
278	    }
279	  }
280	
281	  return false;
282	}
283	
284	/**
285	 * Keyboard navigation for card modal
286	 */
287	/**
288	 * Standard undo hotkey (Ctrl+Z / Cmd+Z).
289	 *
290	 * Clicks the live undo button rendered inside the (possibly hidden) hamburger
291	 * menu, so its current event index and expected-version come along for free.
292	 * Ignored while a modal is open or while typing in a field.
293	 */
294	document.addEventListener('keydown', (event) => {
295	  const isUndo = (event.ctrlKey || event.metaKey) && !event.shiftKey && !event.altKey && event.key.toLowerCase() === 'z';
296	  if (!isUndo) return;
297	
298	  // Don't hijack undo inside text inputs or while a modal is focused.
299	  const target = event.target;
300	  if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return;
301	  if (document.querySelector('.modal-overlay, .card-modal-overlay')) return;
302	
303	  const undoButton = document.querySelector('.undo-button');
304	  if (!undoButton) return;
305	
306	  event.preventDefault();
307	  undoButton.click();
308	});
309	
310	document.addEventListener('keydown', (event) => {
311	  // Check if card modal is open
312	  const modal = document.querySelector('.card-modal-overlay');
313	  if (!modal) return;
314	
315	  // Navigate with arrow keys
316	  if (event.key === 'ArrowLeft') {
317	    const prevButton = modal.querySelector('.card-modal-nav-prev');
318	    if (prevButton) {
319	      prevButton.click();
320	      event.preventDefault(); // Prevent default arrow key behavior
321	    }
322	  } else if (event.key === 'ArrowRight') {
323	    const nextButton = modal.querySelector('.card-modal-nav-next');
324	    if (nextButton) {
325	      nextButton.click();
326	      event.preventDefault(); // Prevent default arrow key behavior
