60	export const OPENING_HAND_SIZE = 7;
61	
62	export interface WhatHappened {
63	  shuffling?: boolean;
64	  movedRight?: GameCard[];
65	  movedLeft?: GameCard[];
66	  dropppedFromLeft?: GameCard;
67	  dropppedFromRight?: GameCard;
68	}
