70	export class GameState {
71	  public readonly gameId: GameId;
72	  private status: GameStatus;
73	  public readonly prepId: PrepId;
74	  public readonly prepVersion: number;
75	  public readonly deckProvenance: DeckProvenance;
76	  public readonly deckName: string;
77	  public readonly deckId: number; // TODO: remove, once it is no longer used in the UI
78	  public readonly totalCards: number;
79	  private readonly gameCards: GameCard[];
80	  private readonly eventLog: GameEventLog;
81	  private readonly randomSeed?: number;
82	
83	  static newGame(gameId: GameId, prepId: PrepId, prepVersion: number, deck: Deck, randomSeed?: number) {
84	    if (deck.commanders.length > 2) {
85	      // TODO: make a warning function, somehow get it into WhatHappened?
86	      console.log("Warning: Deck has more than two commanders. Behavior undefined");
87	    }
88	
89	    // Combine all cards and sort alphabetically (maintaining existing invariant)
90	    const allCards = [...deck.commanders.map((card) => ({ card, isCommander: true })), ...deck.cards.map((card) => ({ card, isCommander: false }))].sort(
91	      (a, b) => a.card.name.localeCompare(b.card.name)
92	    );
93	
94	    let commanderPositionCounter = 0;
95	    let libraryPositionCounter = 0;
96	
97	    const gameCards: GameCard[] = allCards.map((item, index) => ({
98	      card: item.card,
99	      isCommander: item.isCommander,
100	      location: item.isCommander
101	        ? ({ type: "CommandZone", position: commanderPositionCounter++ } as CommandZoneLocation)
102	        : ({ type: "Library", position: libraryPositionCounter++ } as LibraryLocation),
103	      gameCardIndex: index,
104	      currentFace: "front" as const,
105	    }));
106	
107	    return new GameState({
108	      gameId,
109	      gameStatus: GameStatus.Active,
110	      prepId,
111	      prepVersion,
112	      deckId: deck.id,
113	      deckName: deck.name,
114	      deckProvenance: deck.provenance,
115	      cards: gameCards,
