41	  const b = body as Record<string, any>;
42	  if (!b || typeof b !== "object") return "body must be a JSON object";
43	  // JES-128: contract validation goes here.
44	  if (typeof b.id !== "string" || !b.id) return "id (string) is required";
45	  if (b.name !== "card.played") return 'name must be "card.played"';
