47	  if (typeof b.initiator?.playerName !== "string" || !b.initiator.playerName) return "initiator.playerName (string) is required";
48	  if (typeof b.card?.scryfallId !== "string" || !b.card.scryfallId) return "card.scryfallId (string) is required";
