1	function formatHtmlHead(title: string, additionalStylesheets: string[] = []): string {
2	  const additionalStylesheetsHtml = additionalStylesheets.map(href => `    <link rel="stylesheet" href="${href}" />`).join('\n');
3	
4	  return `<head>
5	    <meta charset="UTF-8" />
6	    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
7	    <title>${title}</title>
8	    <link rel="preconnect" href="https://fonts.googleapis.com">
9	    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
10	    <link href="https://fonts.googleapis.com/css2?family=Ovo&family=Orbitron:wght@400;600;700;900&display=swap" rel="stylesheet">
11	    <link rel="stylesheet" href="/styles.css" />
12	    <link rel="stylesheet" href="/game.css" />
13	    <link rel="stylesheet" href="/playmat.css" />
14	${additionalStylesheetsHtml}
15	    <script>
16	      // Generate browserTabId first, before tracing initialization
17	      const SESSION_STORAGE_KEY = "browserTabId";
18	      let browserTabId = sessionStorage.getItem(SESSION_STORAGE_KEY);
19	      if (!browserTabId) {
20	        browserTabId = crypto.randomUUID();
21	        sessionStorage.setItem(SESSION_STORAGE_KEY, browserTabId);
22	      }
23	      window.browserTabId = browserTabId;
24	    </script>
25	    <script src="/hny.js"></script>
26	    <script>
27	      Hny.initializeTracing({
28	        apiKey: "${process.env.HONEYCOMB_INGEST_API_KEY || process.env.HONEYCOMB_API_KEY}",
