input.content:
// Quick prod check: does the tldraw sync websocket connect through the ALB?
import WebSocket from "ws";

const url = "wss://table.jessitron.honeydemo.io/connect/smoke-test?sessionId=smoke-ws-check";
const ws = new WebSocket(url);
const timeout = setTimeout(() => {
  console.log("TIMEOUT: no open event within 10s");
  process.exit(1);
}, 10000);

ws.on("open", () => {
  console.log("WS OPEN: ALB websocket path works");
});
ws.on("message", (data) => {
  const s = data.toString();
  console.log("WS MESSAGE (first 120 chars):", s.slice(0, 120));
  clearTimeout(timeout);
  ws.close();
  process.exit(0);
});
ws.on("error", (err) => {
  console.log("WS ERROR:", err.message);
  clearTimeout(timeout);
  process.exit(1);
});

